def e(s):return escape(str(s),quote=True)
def facts():
 pairs=[(600000,'','normal monthly output'),(800000,'','peak monthly output'),(20000,' m²','company-owned site'),(40000,' m²','building area')]
 return '<div class="facts-grid">'+''.join(f'<div>{count_up(value,unit)}<span>{label}</span></div>' for value,unit,label in pairs)+'</div><p class="section-note capacity-scope">Combined kitchenware, food-storage and cookware output · normal planning basis: 600,000 pieces/month · operating records since 2020.</p>'
def timing():
 pairs=[('Minimum order','1,000 pcs','Per model. Mixed-model shipments supported; smaller orders are subject to small-order charges and confirmation.'),('Custom tooling','30–40 days','Calendar days from the tooling deposit, including mold trials and revisions. A 30-day target applies to suitable projects.'),('Regular production','40–45 days','Calendar days from deposit to production completion. Peak-season planning: 40–50 days. Shipping is additional.')]
 return '<div class="timing-grid">'+''.join(f'<article><span>{a}</span><strong>{b}</strong><p>{c}</p></article>' for a,b,c in pairs)+'</div><p class="section-note">Suitable single-model orders of 3,000–5,000 pieces can start from 30 calendar days. Final timing follows the agreed model, customization and production schedule.</p>'
def revise_page(filename,title,description,body,helper):
 link=helper['link'];heading=helper['heading'];intro=helper['intro'];cta=helper['cta'];image=helper['image'];icon=helper['icon'];steps=helper['steps']
